    PreferenceResponse = apps.get_model("election", "PreferenceResponse")
    ShirtProposal = apps.get_model("election", "ShirtProposal")
    Vote = apps.get_model("election", "Vote")
    database = schema_editor.connection.alias

    for user in User.objects.using(database).all().iterator():
        role = (
            UserProfile.objects.using(database)
            .filter(user_id=user.pk)
            .values_list("role", flat=True)
            .first()
        ) or "STUDENT"
